// Staged hybrid funnel: union recall, fused ordering (plain JS)
function reciprocalRank(rank, k = 60) { return 1 / (k + rank); }
function fuseRRF(rankedLists) {
  // rankedLists: arrays of ids, best-first, one per retriever
  const scores = new Map();
  for (const list of rankedLists)
    list.forEach((id, i) => scores.set(id, (scores.get(id) || 0) + reciprocalRank(i + 1)));
  return [...scores.entries()].sort((a, b) => b[1] - a[1]).map(([id]) => id);
}
// RRF needs only ranks (no score calibration across systems!) — the robust default.

