function reciprocalRank(rank, k) { k = k || 60; return 1 / (k + rank); }
function fuseRRF(rankedLists) {
  const scores = new Map();
  for (const list of rankedLists)
    list.forEach((id, i) => scores.set(id, (scores.get(id) || 0) + reciprocalRank(i + 1)));
  return [...scores.entries()].sort((a, b) => b[1] - a[1]).map((e) => e[0]);
}
const lexical = ['p3-sku-exact', 'p1', 'p2'];
const vector = ['p1', 'p3-sku-exact', 'p4-paraphrase'];
const fused = fuseRRF([lexical, vector]);
console.log(fused.join(','));
console.log('consensus top: ' + (fused[0] === 'p3-sku-exact' || fused[0] === 'p1'));
console.log('union size: ' + fused.length);

